import{_ as o,l,o as e,c,v as r,p as n,x as t,d as p,i,S as d}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"跟踪与 ptrace 入口","description":"","frontmatter":{"title":"跟踪与 ptrace 入口","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/syscall-trace.md","filePath":"cs/syscall-trace.md","lastUpdated":1789023840000}'),h={name:"cs/syscall-trace.md"};function m(E,a,_,f,u,A){const s=l("Mermaid");return e(),c("div",null,[a[1]||(a[1]=r('<h1 id="跟踪与-ptrace-入口" tabindex="-1">跟踪与 ptrace 入口 <a class="header-anchor" href="#跟踪与-ptrace-入口" aria-label="Permalink to &quot;跟踪与 ptrace 入口&quot;">​</a></h1><div class="epigraph"><p>跟踪器不是第三套特权：它只是在系统调用与信号边界上，经内核同意停下被跟踪进程并窥视其 trapframe。</p><footer>—— 据 Love, Linux Kernel Development；Tanenbaum MOS 整理</footer></div><p><a href="/cs/restart-syscall">上一课</a>让返回用户前可能改 PC 以重启调用。<a href="/cs/trapframe">trapframe</a>里已经有完整用户寄存器。缺口是：调试器、<code>strace</code> 一类工具要在<strong>进入/离开系统调用</strong>时停下目标进程、读参数、可选地改返回值。本课只钉这条跟踪入口，不当成调试器产品课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若跟踪器直接改目标内核栈，会破坏<a href="/cs/kernel-user">内核与用户态</a>的门。正确做法是目标在路径边界停进跟踪态，内核把事件报告给跟踪器进程；跟踪器再用专门系统调用读、写目标的帧与内存（仍走拷贝与校验）。缺口不是新的 ABI 编号哲学，而是在<a href="/cs/syscall-path">系统调用路径</a>上插入<strong>可阻塞的观察点</strong>。</p><p>本课不把每一种 <code>PTRACE_*</code> 请求列成手册。</p><p><span class="marginnote">被跟踪进程停在内核认为安全的点：进入调用前、返回用户前、信号递送前。跟踪器自己仍是普通用户进程，只是对目标有内核授予的观察权。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>目标设置「被跟踪」标志。进入分发前：若需 stop-on-enter，则把目标标为停止，唤醒跟踪器，切换走别人。跟踪器读 trapframe 中的调用号与参数寄存器，再让目标继续。返回前同样可停一次，于是 <code>strace</code> 能打印返回值。写寄存器相当于改帧；下次恢复用户态时生效。</p>',9)),(e(),n(d,null,{default:t(()=>[i(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENTER%5B%22%E7%B3%BB%E7%BB%9F%E8%B0%83%E7%94%A8%E5%85%A5%E5%8F%A3%22%5D%20--%3E%20STOP%5B%22%E5%8F%AF%E9%80%89%E5%81%9C%E6%AD%A2%22%5D%0A%20%20STOP%20--%3E%20TRACER%5B%22%E8%B7%9F%E8%B8%AA%E5%99%A8%E8%AF%BB%E5%B8%A7%22%5D%0A%20%20TRACER%20--%3E%20CONT%5B%22%E7%BB%A7%E7%BB%AD%E5%88%86%E5%8F%91%E6%88%96%E8%BF%94%E5%9B%9E%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>权限：通常只有父进程或有能力的调试关系能附上。具体能力模型是安全课；本课只要求不能任意进程互跟。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>跟踪把路径变成可插桩的状态机，而不把内核函数指针交给用户。它与重启的次序要规定好：先决定是否重启，再让跟踪器看见「用户将看到的」调用。多线程目标上，跟踪粒度是线程还是进程，实现各异；主干只要求每条控制流有自己的帧可停。</p><p>性能上，每次调用两次停会毁掉热点路径；默认生产进程不置跟踪位。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写如何绕过跟踪去隐藏系统调用，不把 seccomp-bpf 的过滤程序当攻击面展开。也不把内核探针（kprobe）与用户 ptrace 混成一种机制：前者是内核调试，对象不同。</p><p>后课默认：自愿路径可在边界被观察。设备完成却在 CPU 不知情时到来；若把重活塞进关中断的上半部，延迟不可接受。下一课把中断拆成<a href="/cs/interrupt-bottom-half">下半部</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ptrace 入口：在系统调用与信号边界停止并读改 trapframe。</li><li>跟踪器仍是用户进程；观察权由内核授予。</li><li>设备 IRQ 的推迟处理是下一课。</li><li>出处：Love, <em>LKD</em>；Tanenbaum and Bos, <em>MOS</em>。</li></ul>',9))])}const b=o(h,[["render",m]]);export{T as __pageData,b as default};
